// Additional beginner-to-professional role curricula. The helpers below build
// the same stage, mission, and skill objects consumed by the existing renderer.
const makeRoleRoadmap = (title, description, prefix, stageRows) => ({
  title,
  description,
  stages: stageRows.map(([stageTitle, missionTitle, missionDescription, why, tasks, skillRows]) => ({
    title: stageTitle,
    description: missionDescription,
    mission: { title: missionTitle, description: missionDescription, why, tasks },
    skills: skillRows.map(([id, skillTitle, what, practice, resourceName, url, how, resourceKind]) => {
      const inferredKind = resourceKind || ((prefix === "datasci" || prefix === "analyst")
        ? (/learn\.microsoft|learn\.getdbt|training|career-path|training-path/i.test(url) ? "Course"
          : /tutorial|quickstart|sqlbolt|getting_started/i.test(url) ? "Tutorial" : "Documentation")
        : undefined);
      return skill(`${prefix}-${id}`, skillTitle, what, how || "Study the linked free guide, then apply its concepts in the practice task.", practice, [resource(resourceName, url, inferredKind)]);
    })
  }))
});

// Compact authoring helper for additional career-specific curricula. It expands
// each skill row into the stageRows format above, so the renderer sees the same
// roadmap, mission, and skill objects as every existing role.
const makeCareerRoadmap = (role, description, prefix, stages) => makeRoleRoadmap(
  `${role} Roadmap`, description, prefix,
  stages.map(([stage, mission, missionDescription, why, tasks, skills]) => [
    stage, mission, missionDescription, why, tasks,
    skills.map(([id, title, what, resourceName, url, practice]) => [
      id, title, what, practice,
      resourceName, url,
      `Study ${title.toLowerCase()} in the linked free resource, take concise notes, then apply one concept at a time in a small lab or project.`,
      "Documentation"
    ])
  ])
);
const makeEightStageRoadmap = (role, description, prefix, rows) => makeCareerRoadmap(
  role, description, prefix,
  rows.map(([stage, mission, focus, skills], index) => [
    stage, mission, focus,
    `Stage ${index + 1} builds ${focus.toLowerCase()} so you can progress toward independent ${role.toLowerCase()} work.`,
    [`Study ${stage.toLowerCase()} concepts`, `Apply ${focus.toLowerCase()} in a safe practice environment`, `Record the result and explain your decisions`],
    skills.map(([id, title, what, resourceName, url]) => [id, title, what, resourceName, url,
      `Create a small, documented exercise demonstrating ${title.toLowerCase()}; include expected behavior, observations, and one improvement.`])
  ])
);

