    ["API Automation", "Build an API regression suite", "Automate service contract, negative, and stateful API behaviors.", [["api","HTTP API automation","Send requests and verify status, headers, payload, and error behavior.","Postman Learning Center","https://learning.postman.com/"],["contracts","Contract and schema checks","Check response structure and compatibility with agreed API contracts.","OpenAPI Specification","https://spec.openapis.org/oas/latest.html"],["negative","Negative and boundary testing","Exercise invalid input, authorization boundaries, and edge conditions safely.","OWASP API Security Top 10","https://owasp.org/www-project-api-security/"]]],
    ["Mocks, Dependencies, and Test Doubles", "Test components with controlled dependencies", "Use test doubles carefully while retaining confidence in integration behavior.", [["mocking","Mocking concepts","Distinguish mocks, stubs, fakes, and real dependencies by test purpose.","unittest.mock","https://docs.python.org/3/library/unittest.mock.html"],["integration","Integration test boundaries","Choose realistic service boundaries and isolate external systems where useful.","pytest Good Integration Practices","https://docs.pytest.org/en/stable/explanation/goodpractices.html"],["determinism","Deterministic test design","Control clocks, randomness, and external state for repeatable results.","pytest flaky tests","https://docs.pytest.org/en/stable/explanation/flaky.html"]]],
    ["Reporting and CI", "Publish useful test results in CI", "Integrate suites into automated workflows and make failure diagnosis efficient.", [["reports","Test reporting","Produce clear reports, artifacts, and failure context for a team.","pytest JUnit XML","https://docs.pytest.org/en/stable/how-to/output.html"],["ci","CI/CD test integration","Run selected suites on changes and manage artifacts and secrets safely.","GitHub Actions","https://docs.github.com/en/actions"],["containers","Containerized test environments","Use reproducible environments for local and continuous test execution.","Docker Get Started","https://docs.docker.com/get-started/"]]],
    ["Framework Reliability and Scale", "Improve framework reliability", "Manage flakiness, test selection, maintainability, and execution cost.", [["flaky","Flaky test diagnosis","Identify timing, isolation, and dependency causes instead of hiding failures.","Playwright Best Practices","https://playwright.dev/docs/best-practices"],["selection","Test pyramid and selection","Balance fast unit checks and broader integration/end-to-end coverage.","Google Testing Blog","https://testing.googleblog.com/"],["maintenance","Automation code review","Refactor duplicated helpers and track maintenance burden over time.","Selenium Practices","https://www.selenium.dev/documentation/test_practices/"]]],
    ["SDET Capstone", "Deliver a maintainable automation framework", "Publish UI and API test suites with reusable fixtures, CI results, and contributor guidance.", [["capstone-design","Framework design","Define supported layers, conventions, data strategy, and extension points.","pytest Documentation","https://docs.pytest.org/en/stable/"],["capstone-build","Framework implementation","Implement representative UI and API checks with deterministic setup and useful reports.","Playwright Docs","https://playwright.dev/docs/intro"],["capstone","SDET portfolio capstone","Demonstrate architecture, maintainability, parallel execution, CI integration, and clear failure diagnosis.","GitHub Actions","https://docs.github.com/en/actions"]]]
