  const makeAISpecializationRoadmap = (role, description, prefix, stages) => ({
    title: `${role} Roadmap`,
    description,
    stages: stages.map(([title, stageDescription, missionTitle, missionWhy, tasks, rows]) => ({
      title,
      description: stageDescription,
      mission: { title: missionTitle, description: stageDescription, why: missionWhy, tasks },
      skills: rows.map(([id, name, what, how, practice, resources]) =>
        skill(`${prefix}-${id}`, name, what, how, practice, resources.map(([resourceName, url, type]) => resource(resourceName, url, type)))
      )
    }))
  });

